('editorial', 'Editorial', 'Story-Driven. Stylised. Striking.', 'A cinematic, magazine-worthy aesthetic. Expressive and fashion-forward — stand out with personality and mood.', '["outdoor-fashion-1.webp","outdoor-fashion-2.webp","outdoor-fashion-3.webp","outdoor-fashion-4.webp","outdoor-fashion-4.webp"]', ARRAY['male','female'], ARRAY['plain-light','plain-dark','plain-orange','plain-blue','plain-teal','studio','gradient','brick'], ARRAY['hoodie','shirt','polo','henley','jacket','fishermans-jumper'], ARRAY['#000000','#FFFFFF','#2A9D47','#3B82F6','#FF7F39','#D22D2D','#FC84E2','#A28DF7','#6B7280','#4F46E5'], '2025-04-23 23:42:59.539907+00', '2025-04-23 23:42:59.539907+00'),
('studio', 'Studio', 'Polished. Professional. Powerful.', 'Step into the spotlight with Studio style — clean, high-impact headshots perfect for portfolios, castings, and personal branding.', '["studio-1.webp","studio-2.webp","studio-3.webp","studio-1.webp","studio-2.webp"]', ARRAY['male','female'], ARRAY['plain-light','plain-dark','plain-orange','plain-blue','plain-teal','studio','gradient','brick'], ARRAY['hoodie','suit-jacket-shirt','shirt','polo','henley','jacket','fishermans-jumper'], ARRAY['#000000','#FFFFFF','#2A9D47','#3B82F6','#FF7F39','#D22D2D','#FC84E2','#A28DF7','#6B7280','#4F46E5'], '2025-04-23 23:42:59.539907+00', '2025-04-23 23:42:59.539907+00');
